package org.brightstats.stats;

import java.util.*;

/** Elastic-net RAM path/loading estimation with genuinely nested held-out selection. */
public final class RegularizedSem {
    private RegularizedSem(){}
    public record Target(String parameter,double center,double scale){public Target{if(parameter==null||parameter.isBlank()||!Double.isFinite(center)||!(scale>0)||!Double.isFinite(scale))throw new IllegalArgumentException("Declare a named penalty target, finite center and positive fixed raw-unit scale.");}}
    public record Options(List<Target> targets,double[] lambdas,double mixing,int outerFolds,int innerFolds,long seed,int maxIterations,double tolerance,double selectionTolerance){
        public Options{targets=List.copyOf(targets);lambdas=lambdas.clone();if(targets.isEmpty()||new HashSet<>(targets.stream().map(Target::parameter).toList()).size()!=targets.size()||lambdas.length<2||lambdas.length>12||Arrays.stream(lambdas).anyMatch(x->!Double.isFinite(x)||x<0)||Arrays.stream(lambdas).distinct().count()!=lambdas.length||Arrays.stream(lambdas).noneMatch(x->x==0)||!Double.isFinite(mixing)||mixing<0||mixing>1||outerFolds<2||outerFolds>10||innerFolds<2||innerFolds>10||(long)(outerFolds+1)*innerFolds*lambdas.length+outerFolds+1>250||maxIterations<20||maxIterations>10000||!(tolerance>0)||!Double.isFinite(tolerance)||!(selectionTolerance>0)||!Double.isFinite(selectionTolerance))throw new IllegalArgumentException("Provide distinct penalty targets, 2–12 nonnegative lambdas including zero, mixing in [0,1], 2–10 inner/outer folds and at most 250 planned fits.");}
        @Override public double[] lambdas(){return lambdas.clone();}
    }
    public record Estimate(String parameter,double estimate,boolean penalized,Double penaltyCenter,Double penaltyScale){}
    public record Candidate(double lambda,Double heldOutMeanNegativeLogLikelihood,int successfulFolds,int attemptedFolds,List<String> failures){public Candidate{failures=List.copyOf(failures);}}
    public record OuterFold(int index,List<Integer> trainingRows,List<Integer> heldOutRows,double selectedLambda,double heldOutMeanNegativeLogLikelihood,List<Candidate> innerSelection,double[] estimates){public OuterFold{trainingRows=List.copyOf(trainingRows);heldOutRows=List.copyOf(heldOutRows);innerSelection=List.copyOf(innerSelection);estimates=estimates.clone();}@Override public double[] estimates(){return estimates.clone();}}
    public record Stability(String parameter,int outerFits,double frequencyAwayFromPenaltyCenter,double medianEstimate,double lowerQuartile,double upperQuartile){}
    public record Fit(SemModel.Model model,Options options,int observations,double selectedLambda,int finalIterations,boolean converged,double trainingMeanNegativeLogLikelihood,double penalty,double nestedHeldOutMeanNegativeLogLikelihood,List<Estimate> estimates,List<Candidate> finalInnerSelection,List<OuterFold> outerValidation,List<Stability> stability,int completedFits,List<String> warnings){public Fit{estimates=List.copyOf(estimates);finalInnerSelection=List.copyOf(finalInnerSelection);outerValidation=List.copyOf(outerValidation);stability=List.copyOf(stability);warnings=List.copyOf(warnings);}}
    record Optimized(double[] theta,int iterations,boolean converged,double likelihood,double penalty){}
    record Selection(double lambda,List<Candidate> candidates){}
    static final class Penalty {
        final double[] k,center;final Options options;
        Penalty(SemModel.Model model,Options options){this.options=options;k=new double[model.parameters().size()];center=new double[k.length];Map<String,Integer> indices=new HashMap<>();for(int j=0;j<k.length;j++)indices.put(model.parameters().get(j).name(),j);for(var target:options.targets()){Integer index=indices.get(target.parameter());if(index==null)throw new IllegalArgumentException("Unknown penalty target: "+target.parameter());var parameter=model.parameters().get(index);if(parameter.locations().stream().anyMatch(l->l.kind()!=SemModel.Kind.DIRECTED))throw new IllegalArgumentException("Current elastic-net penalties target directed paths/loadings only; do not penalize means or covariance components.");k[index]=parameter.scale()/target.scale();center[index]=target.center()/parameter.scale();}}
        double value(double[] theta,double lambda){double value=0;for(int j=0;j<theta.length;j++){double z=k[j]*(theta[j]-center[j]);value+=lambda*(options.mixing()*Math.abs(z)+(1-options.mixing())*z*z/2);}return value;}
        double smooth(double[] theta,double lambda){double value=0;for(int j=0;j<theta.length;j++){double z=k[j]*(theta[j]-center[j]);value+=lambda*(1-options.mixing())*z*z/2;}return value;}
        double[] gradient(double[] theta,double lambda){double[] out=new double[theta.length];for(int j=0;j<out.length;j++)out[j]=lambda*(1-options.mixing())*k[j]*k[j]*(theta[j]-center[j]);return out;}
    }
    static Optimized optimize(double[][] data,SemModel.Model model,Options options,double lambda){
        var work=new SemObservedLikelihood(data,model);var penalty=new Penalty(model,options);double[] theta=work.initial(),low=work.lower(),high=work.upper();var current=work.evaluate(theta);if(!Double.isFinite(current.value()))throw new IllegalArgumentException("Regularized model starting state is inadmissible.");double step=1;
        for(int iteration=0;iteration<options.maxIterations();iteration++){
            Matrices.interrupted();double[] gradient=current.gradient(),ridge=penalty.gradient(theta,lambda);for(int j=0;j<gradient.length;j++)gradient[j]+=ridge[j];double smooth=current.value()+penalty.smooth(theta,lambda),full=current.value()+penalty.value(theta,lambda);boolean accepted=false;double[] candidate=new double[theta.length];Bfgs.Evaluation next=null;double mapping=Double.POSITIVE_INFINITY;
            while(step>=1e-14){
                double linear=0,square=0;mapping=0;for(int j=0;j<theta.length;j++){double proposed=theta[j]-step*gradient[j]-penalty.center[j],threshold=step*lambda*options.mixing()*penalty.k[j];candidate[j]=Math.max(low[j],Math.min(high[j],penalty.center[j]+Math.copySign(Math.max(0,Math.abs(proposed)-threshold),proposed)));double delta=candidate[j]-theta[j];linear+=gradient[j]*delta;square+=delta*delta;mapping=Math.max(mapping,Math.abs(delta)/step);}next=work.evaluate(candidate);if(Double.isFinite(next.value())&&next.value()+penalty.smooth(candidate,lambda)<=smooth+linear+square/(2*step)+1e-13&&next.value()+penalty.value(candidate,lambda)<=full+1e-13){accepted=true;break;}step*=.5;
            }
            if(!accepted)return new Optimized(theta,iteration,false,current.value(),penalty.value(theta,lambda));theta=candidate.clone();current=next;if(mapping<=options.tolerance())return new Optimized(theta,iteration+1,true,current.value(),penalty.value(theta,lambda));step=Math.min(10,step*1.2);
        }
        return new Optimized(theta,options.maxIterations(),false,current.value(),penalty.value(theta,lambda));
    }
    public static Fit fit(double[][] data,SemModel.Model model,Options options,java.util.function.IntConsumer progress){
        int p=Matrices.width(data,30),n=data.length;if(n>5000||p>32||model.parameters().size()>80||model.variables().size()>64||p!=model.observed().length||Arrays.stream(data).flatMapToDouble(Arrays::stream).anyMatch(x->!Double.isFinite(x)))throw new IllegalArgumentException("Nested regularized SEM requires complete finite selected data, 30–5,000 rows, at most 32 observed/64 total variables and 80 parameters.");new Penalty(model,options);if(n/options.outerFolds()<3||(n-n/options.outerFolds())/options.innerFolds()<3)throw new IllegalArgumentException("Every held-out fold needs at least three rows.");int[] completed={0};List<Integer> all=java.util.stream.IntStream.range(0,n).boxed().toList();List<List<Integer>> outer=folds(all,options.outerFolds(),options.seed());List<OuterFold> validation=new ArrayList<>();double heldOut=0;
        for(int index=0;index<outer.size();index++){
            List<Integer> test=outer.get(index),train=without(all,test);var selection=select(data,train,model,options,options.seed()+1009L*(index+1),completed,progress);var fit=optimize(rows(data,train),model,options,selection.lambda());completed(completed,progress);if(!fit.converged())throw new IllegalArgumentException("Outer training refit did not converge in fold "+(index+1)+"; nested performance is unavailable.");double score=new SemObservedLikelihood(rows(data,test),model).evaluate(fit.theta()).value();if(!Double.isFinite(score))throw new IllegalArgumentException("Outer held-out likelihood is nonfinite.");heldOut+=score*test.size();double[] estimates=raw(fit.theta(),model);validation.add(new OuterFold(index+1,oneBased(train),oneBased(test),selection.lambda(),score,selection.candidates(),estimates));
        }
        var finalSelection=select(data,all,model,options,options.seed()+900001,completed,progress);var finalFit=optimize(data,model,options,finalSelection.lambda());completed(completed,progress);if(!finalFit.converged())throw new IllegalArgumentException("Final regularized refit did not converge; no completed result is returned.");Map<String,Target> targets=new HashMap<>();options.targets().forEach(t->targets.put(t.parameter(),t));List<Estimate> estimates=new ArrayList<>();List<Stability> stability=new ArrayList<>();double[] raw=raw(finalFit.theta(),model);
        for(int j=0;j<raw.length;j++){var parameter=model.parameters().get(j);var target=targets.get(parameter.name());estimates.add(new Estimate(parameter.name(),raw[j],target!=null,target==null?null:target.center(),target==null?null:target.scale()));if(target!=null){final int col=j;double[] values=validation.stream().mapToDouble(v->v.estimates[col]).sorted().toArray();long active=Arrays.stream(values).filter(v->Math.abs((v-target.center())/target.scale())>options.selectionTolerance()).count();stability.add(new Stability(parameter.name(),values.length,active/(double)values.length,ClusterSem.quantile(values,.5),ClusterSem.quantile(values,.25),ClusterSem.quantile(values,.75)));}}
        List<String> warnings=List.of("Elastic-net penalties use declared fixed raw-unit centers/scales for directed paths/loadings. Model specification and penalty scales must be prespecified independently of held-out outcomes. The Gaussian likelihood is fit to complete selected data; ordinal, missing-data and clustered nested-validation procedures are not supplied.","Each outer fold chooses lambda exclusively from its own training rows using inner held-out mean negative log likelihood, then refits and evaluates its untouched outer rows. The final lambda uses a separate full-data inner CV. Any failed inner fit disqualifies that candidate; failures are not silently omitted. Ties prefer the larger lambda.","Reported nested held-out performance evaluates the selection procedure, not the final full-data fit. Stability summarizes outer training refits and is not a formal selection probability. No ordinary post-selection SE, P values or global fit-test claims are supplied.","Proximal gradient uses admissibility-preserving backtracking and local convergence; nonconvex SEM may have local optima. Ridge generally does not produce exact zeros; activity uses the declared scaled tolerance.");return new Fit(model,options,n,finalSelection.lambda(),finalFit.iterations(),finalFit.converged(),finalFit.likelihood(),finalFit.penalty(),heldOut/n,estimates,finalSelection.candidates(),validation,stability,completed[0],warnings);
    }
    static Selection select(double[][] data,List<Integer> population,SemModel.Model model,Options options,long seed,int[] completed,java.util.function.IntConsumer progress){List<List<Integer>> folds=folds(population,options.innerFolds(),seed);List<Candidate> candidates=new ArrayList<>();double best=Double.POSITIVE_INFINITY,chosen=Double.NaN;for(double lambda:options.lambdas()){double total=0;int successful=0;List<String> failures=new ArrayList<>();for(int fold=0;fold<folds.size();fold++){Matrices.interrupted();var test=folds.get(fold);var train=without(population,test);try{var fit=optimize(rows(data,train),model,options,lambda);if(!fit.converged())throw new IllegalArgumentException("Optimizer did not converge");double loss=new SemObservedLikelihood(rows(data,test),model).evaluate(fit.theta()).value();if(!Double.isFinite(loss))throw new IllegalArgumentException("Held-out likelihood is nonfinite");total+=test.size()*loss;successful++;}catch(java.util.concurrent.CancellationException cancelled){throw cancelled;}catch(RuntimeException invalid){failures.add("Fold "+(fold+1)+": "+Objects.toString(invalid.getMessage(),invalid.getClass().getSimpleName()));}completed(completed,progress);}Double score=successful==folds.size()?total/population.size():null;candidates.add(new Candidate(lambda,score,successful,folds.size(),failures));if(score!=null&&(score<best-1e-12||Math.abs(score-best)<=1e-12&&lambda>chosen)){best=score;chosen=lambda;}}if(!Double.isFinite(chosen))throw new IllegalArgumentException("Every lambda candidate failed at least one inner fold; no candidate is selected.");return new Selection(chosen,List.copyOf(candidates));}
    static void completed(int[] count,java.util.function.IntConsumer progress){count[0]++;if(progress!=null)progress.accept(count[0]);}
    static List<List<Integer>> folds(List<Integer> population,int count,long seed){List<Integer> shuffled=new ArrayList<>(population);Collections.shuffle(shuffled,new Random(seed));List<List<Integer>> result=new ArrayList<>();for(int j=0;j<count;j++)result.add(new ArrayList<>());for(int j=0;j<shuffled.size();j++)result.get(j%count).add(shuffled.get(j));return result.stream().map(List::copyOf).toList();}
    static List<Integer> without(List<Integer> population,List<Integer> excluded){Set<Integer> set=new HashSet<>(excluded);return population.stream().filter(i->!set.contains(i)).toList();}
    static List<Integer> oneBased(List<Integer> rows){return rows.stream().map(i->i+1).toList();}
    static double[][] rows(double[][] data,List<Integer> rows){double[][] out=new double[rows.size()][];for(int j=0;j<out.length;j++)out[j]=data[rows.get(j)].clone();return out;}
    static double[] raw(double[] theta,SemModel.Model model){double[] raw=theta.clone();for(int j=0;j<raw.length;j++)raw[j]*=model.parameters().get(j).scale();return raw;}
}
